 internal static string T(string source) {
  string[] variants;
  return Text.TryGetValue(source,out variants)?variants[Math.Max(0,Column)]:source;
 }
 internal static void Apply(DependencyObject element) {
  var text=element as TextBlock;
  if(text!=null)text.Text=T(text.Text);
  var content=element as ContentControl;
  if(content!=null&&content.Content is string)content.Content=T((string)content.Content);
  foreach(object child in LogicalTreeHelper.GetChildren(element)) {
   var node=child as DependencyObject;
   if(node!=null)Apply(node);
  }
 }
}
